Page._content:
.callout {
    border-left: 5px solid #ccc;
    padding: 1em;
    margin: 1.5em 0;
    border-radius: 10px;
    background: #f9f9f9;
}

.callout-info {
    border-color: #2196f3;
    background: #e3f2fd;
}
.callout-tip {
    border-color: #4caf50;
    background: #e8f5e9;
}
.callout-warning {
    border-color: #ff9800;
    background: #fff3e0;
}
.callout-danger {
    border-color: #f44336;
    background: #ffebee;
}

.callout-title {
    font-weight: bold;
    margin-bottom: 0.5em;
}

