      </el-table-column>
      <el-table-column
          prop="start_date"
          label="Start Date">
      </el-table-column>
      <el-table-column
          prop="due_date"
          label="Due Date">
      </el-table-column>
      <el-table-column
          prop="status"
          label="Status">
      </el-table-column>
      <el-table-column
          prop="priority"
          label="Priority">
      </el-table-column>
      <el-table-column
          prop="description"
          label="Description">
      </el-table-column>
      <el-table-column
          prop="created_at"
          label="Create Date">
      </el-table-column>
    </el-table>
  </div>
</template>

<script>
export default {
  name: "GetJson",
  created() {
  },
  data() {
    return {
      model : {
        title : '제목',
        status : '1',
        priority : '1',
        description: '내용',
      },
      tasks : [],
    }
  },
  methods: {
    create() {
      if(this.model.title != '' &&
          this.model.status != '' &&
          this.model.priority != '' &&
          this.model.description != '') {
        this.$http.post('https://goodsaem.ml/tasks',[this.model]).then((response) => {
          this.$message('정상적으로 저장되었습니다.');
        }).catch((err) =>{
          this.$message(err);
        });
      }
    },
    search() {
      this.$http.get('https://goodsaem.ml/tasks').then((response) => {
        this.tasks = response.data;
      })
    }
  }
}
</script>

